from pathlib import Path
for p in ["benchmark/writing/c1-challenges-0125-cases.json","benchmark/writing/c1-challenges-0125-expectations.json"]:
 d=json.loads(Path(p).read_text()); print("FILE",p,"TOP KEYS",list(d))
 if "citation_registry" in d:
  for k in ["conditions","citation_registry"]: print(k,json.dumps(d[k],ensure_ascii=False,indent=2))
 print("N08",json.dumps(d["cases"][7],ensure_ascii=False,indent=2))
for p in ["benchmark/writing/method.json","benchmark/writing/wp1-key-0119.json"]:
 d=json.loads(Path(p).read_text()); print("FILE",p)
 if "common" in d:
  print(json.dumps({"answer_rule":d["common"]["answer_rule"],"task4":d["tasks"][4]},ensure_ascii=False,indent=2))
 else:
  print(json.dumps({"C1":d["finding_dispositions"]["C1"],"claim_adjudication":d["claim_adjudication"],"required_ids":d["required_ids"][5:8]},ensure_ascii=False,indent=2))
p=Path("benchmark/protocol.md"); lines=p.read_text().splitlines()
for a,b in [(29,41),(60,62),(125,125)]:
 for n in range(a,b+1): print(str(n)+": "+lines[n-1])'

